void malidp_error ( struct malidp_drm * malidp , struct malidp_error_stats * error_stats , u32 status , u64 vblank ) { cfs_time_t irqflags ; spin_lock_irqsave ( & malidp -> errors_lock , irqflags ) ; error_stats -> last_error_status = status ; error_stats -> last_error_vblank = vblank ; error_stats -> num_errors ++ ; spin_unlock_irqrestore ( & malidp -> errors_lock , irqflags ) ; } 